  const x = data[i++] - 1;
  const y = data[i++] - 1;
  black[x][y] = true;
}

const eligible = Array.from({ length: L }, () => Array(C).fill(false));
const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
let count = 0;

for (let r = 0; r < L; r++) {
  for (let c = 0; c < C; c++) {
    if (black[r][c]) continue;
    for (const [dr, dc] of dirs) {
      const nr = r + dr;
      const nc = c + dc;
      if (nr >= 0 && nr < L && nc >= 0 && nc < C && black[nr][nc]) {
        eligible[r][c] = true;
        count++;
        break;
      }
    }
  }
}

const match = Array.from({ length: L }, () => Array(C).fill(null));

function findMatch(r, c, seen) {
  for (const [dr, dc] of dirs) {
    const nr = r + dr;
    const nc = c + dc;
    if (
      nr < 0 || nr >= L || nc < 0 || nc >= C ||
      !eligible[nr][nc] || seen[nr][nc]
    ) continue;

    seen[nr][nc] = true;
    if (match[nr][nc] === null || findMatch(match[nr][nc][0], match[nr][nc][1], seen)) {
      match[nr][nc] = [r, c];
      return true;
    }
  }
  return false;
}

let matching = 0;
for (let r = 0; r < L; r++) {
  for (let c = 0; c < C; c++) {
    if (eligible[r][c] && (r + c) % 2 === 0) {
      const seen = Array.from({ length: L }, () => Array(C).fill(false));
      if (findMatch(r, c, seen)) matching++;
    }
  }
}

console.log(count - matching);
